import pandas as pd,numpy as np
from scipy.stats import spearmanr
from sklearn.metrics import pairwise_distances
tr=pd.read_csv('b3_te_zt_extrapolation_train.csv'); po=pd.read_csv('b3_te_zt_extrapolation_pool.csv'); cc=[c for c in tr if c not in ['T','target']]

def pred_local(train,test,tt,k=None,h=None,p=2,ridge=0, extrap='linear'):
 D=pairwise_distances(test[cc],train[cc]); out=[]
 for ds in D:
  if k: use=np.argsort(ds)[:k]
  else: use=np.arange(len(ds))
  dd=ds[use]
  if h: w=np.exp(-(dd/h)**p)
  else: w=1/(dd+.01)**p
  # weighted means each temp, then linear regression temp means; account available samples
  T=train['T'].values[use]; y=train.target.values[use]
  # weighted linear regression
  X=np.array([np.ones(len(T)),(T-400)/100]).T
  A=X.T@(w[:,None]*X)+np.diag([ridge,ridge]); b=X.T@(w*y)
  coef=np.linalg.solve(A,b)
  z=(tt-400)/100
  out.append(coef[0]+coef[1]*z)
 return np.array(out)

for testt in [500]:
 a=tr[(tr['T']<testt)&(tr.target<2)]; b=tr[tr['T']==testt]
 print('eval',len(a),len(b))
 for k in [5,10,15,20,30,50,100,180]:
  for p in [1,2,4]:
   try: pr=pred_local(a,b,testt,k=k,p=p,ridge=1e-6)
   except: continue
   rho=spearmanr(pr,b.target).statistic; top=b.iloc[np.argsort(-pr)[:10]]; rec=len(set(top.index)&set(b.nlargest(10,'target').index))
   print(f'k{k}p{p} rho{rho:.3f} top5mean{top.target[:5].mean():.3f} top10{top.target.mean():.3f} rec{rec} ids',list(top.index[:5]))
 for h in [.02,.03,.05,.08,.1,.15,.2,.3,.5,1]:
  for p in [1,2]:
   try:pr=pred_local(a,b,testt,h=h,p=p,ridge=1e-6)
   except:continue
   rho=spearmanr(pr,b.target).statistic; top=b.iloc[np.argsort(-pr)[:10]]; rec=len(set(top.index)&set(b.nlargest(10,'target').index))
   print(f'h{h}p{p} rho{rho:.3f} top5mean{top.target[:5].mean():.3f} top10{top.target.mean():.3f} rec{rec} ids',list(top.index[:5]))

# Pool predictions selected
A=tr[tr.target<2]
P=pd.DataFrame(index=po.candidate_id)
for k in [5,10,15,20,30,50,100]:
 for p in [1,2,4]:P[f'k{k}p{p}']=pred_local(A,po,800,k=k,p=p,ridge=1e-6)
for h in [.03,.05,.08,.1,.15,.2,.3,.5]:
 for p in [1,2]:P[f'h{h}p{p}']=pred_local(A,po,800,h=h,p=p,ridge=1e-6)
P['rankavg']=P.rank(ascending=False,pct=True).mean(axis=1)
print('\n',P.nsmallest(30,'rankavg')[['rankavg']+list(P.columns[:10])].round(3).to_string())
